mapper.select:
SELECT a.*, s.name AS shop_name, st.name AS store_name, o.erp_status AS order_erp_status
FROM ch_wx_aftersale a
JOIN ch_wx_shop s ON s.id = a.shop_id
LEFT JOIN store_info st ON st.id = a.store_id
LEFT JOIN ch_wx_order o ON o.id = a.wx_order_id

    a.shop_id = #{q.shopId}
    AND a.store_id = #{q.storeId}
    AND a.type = #{q.type}
    AND a.status = #{q.status}
    AND a.erp_status = #{q.erpStatus}
    AND a.apply_time >= #{q.beginDate}
    AND a.apply_time < #{q.endNext}

        AND (a.aftersale_id LIKE CONCAT('%', #{q.keyword}, '%') OR a.order_id LIKE CONCAT('%', #{q.keyword}, '%')
             OR a.title LIKE CONCAT('%', #{q.keyword}, '%'))


ORDER BY a.apply_time DESC, a.id DESC
